"""Helpers for TTDL's ``tmr`` and ``spent`` todo.txt tags."""
import re

_TAG = re.compile(r"(?<!\S)(tmr|spent):([^\s]+)")


def timer_values(text):
    """Return (timer epoch or None, spent seconds) from a task's raw text."""
    values = {k: v for k, v in _TAG.findall(text)}
    timer = None
    if values.get("tmr", "off") != "off":
        try:
            timer = int(values["tmr"])
        except (ValueError, KeyError):
            pass
    try:
        spent = max(0, int(values.get("spent", "0")))
    except ValueError:
        spent = 0
    return timer, spent


def set_timer_tag(text, value):
    """Set or append tmr tag, preserving all other text and tags."""
    token = "tmr:" + str(value)
    if re.search(r"(?<!\S)tmr:[^\s]+", text):
        return re.sub(r"(?<!\S)tmr:[^\s]+", token, text, count=1)
    return text.rstrip() + " " + token


def set_spent_tag(text, seconds):
    """Set or append spent tag using TTDL's integer seconds representation."""
    token = "spent:" + str(max(0, int(seconds)))
    if re.search(r"(?<!\S)spent:[^\s]+", text):
        return re.sub(r"(?<!\S)spent:[^\s]+", token, text, count=1)
    return text.rstrip() + " " + token


def start_timer(text, now):
    timer, _ = timer_values(text)
    if timer is not None:
        return text
    return set_timer_tag(text, int(now))


def stop_timer(text, now):
    """Stop an active timer. Return (new_text, changed)."""
    timer, _ = timer_values(text)
    if timer is None:
        return text, False
    text = set_timer_tag(text, "off")
    # TTDL records the just-finished run as spent; it does not add the old
    # spent value here (the UI's spent field is maintained separately).
    text = set_spent_tag(text, max(0, int(now) - timer))
    return text, True

