def _duration(value):
    """Parse conventional spent values to seconds."""
    import re
    if value is None:
        return 0
    text = str(value).strip()
    total = 0
    for number, unit in re.findall(r"(\d+(?:\.\d+)?)([smhdDwMyY]?)", text):
        amount = float(number)
        total += amount * {"": 1, "s": 1, "m": 60, "h": 3600, "d": 86400,
                           "D": 86400, "w": 604800, "M": 2592000,
                           "y": 31536000, "Y": 31536000}.get(unit, 1)
    return int(total)


def _spent(row):
    return _duration(_tag(row, "spent"))


def _fmt_spent(seconds):
    if not seconds:
        return ""
    if seconds < 60:
        return f"{seconds}s"
    if seconds < 3600:
        return f"{seconds / 60:.1f}m"
    if seconds < 86400:
        return f"{seconds / 3600:.1f}h"
    return f"{seconds / 86400:.1f}D"


