def parse(line):
    s=line.rstrip('\n'); d={'raw':s,'done':False,'pri':'','created':'','finished':'','tags':{}}
    if s.startswith('x '):
        d['done']=True; s=s[2:]
        m=re.match(r'\(([A-Z])\)\s*',s)
        if m: d['pri']=m.group(1); s=s[m.end():]
        m=re.match(r'(\d{4}-\d\d-\d\d)(?:\s+|$)',s)
        if m: d['finished']=m.group(1); s=s[m.end():]
    if not d['pri'] and not d['done']:
        m=re.match(r'\(([A-Z])\)\s*',s)
        if m: d['pri']=m.group(1); s=s[m.end():]
    m=re.match(r'(\d{4}-\d\d-\d\d)(?:\s+|$)',s)
    if m: d['created']=m.group(1); s=s[m.end():]
    d['subject']=s
    for m in re.finditer(r'(?<!\S)([\w!]+):([^\s]+)',s): d['tags'][m.group(1)]=m.group(2)
    d['projects']=re.findall(r'(?<!\S)\+([^\s]+)',s); d['contexts']=re.findall(r'(?<!\S)@([^\s]+)',s)
    d['due']=d['tags'].get('due',''); d['rec']=d['tags'].get('rec','')
    d['threshold']=d['tags'].get('t',d['tags'].get('threshold',''))
    return d
def show_fields_value(d,field):
