def resolve_date_tags(subject):
    pairs=re.findall(r'(?<!\S)([\w!]+):([^\s]+)',subject)
    values={k.lower():v for k,v in pairs}
    for key in ('due','t','threshold'):
        if key not in values: continue
        try:
            resolved=parse_date_expression(values[key],TODAY,values).isoformat()
            subject=re.sub(r'(?<!\S)'+re.escape(key)+r':[^\s]+',key+':'+resolved,subject,count=1)
            values[key]=resolved
        except (ValueError, RecursionError):
            pass
    return subject

